void celt_tx_mdct_inv_float_neonemu(const OpusTXContext* s, void* out, void* in, ptrdiff_t stride) { neonemu_call(4, s, out, in, stride); }
void celt_tx_fft32_ns_float_neonemu(const OpusTXContext* s, void* out, void* in, ptrdiff_t stride) { neonemu_call(5, s, out, in, stride); }
void celt_tx_fft_sr_ns_float_neonemu(const OpusTXContext* s, void* out, void* in, ptrdiff_t stride) { neonemu_call(6, s, out, in, stride); }

